 use docfit_config::{get, migrate, read_json, set, validate_patch, SettingsError};
use serde_json::{json, Value};
use std::{env, path::PathBuf, process};
fn output(result:Result<Value,SettingsError>){match result{Ok(v)=>println!("{}",serde_json::to_string(&json!({"ok":true,"value":v})).unwrap()),Err(e)=>{println!("{}",serde_json::to_string(&json!({"ok":false,"code":e.code,"message":e.message})).unwrap());process::exit(2)}}}
fn main(){let mut a=env::args().skip(1);let Some(cmd)=a.next() else{eprintln!("usage: settings-core get|set|migrate [path] [json]");process::exit(64)};let path=PathBuf::from(a.next().unwrap_or_else(||docfit_config::settings_path().to_string_lossy().into_owned()));let input=a.next();match cmd.as_str(){"get"=>output(get(&path)),"migrate"=>output(read_json(&path).map(|v|migrate(&v))),"validate"=>{let Some(s)=input else{eprintln!("validate requires patch JSON");process::exit(64)};let patch=serde_json::from_str(&s).unwrap_or_else(|e|{eprintln!("invalid patch JSON: {e}");process::exit(64)});output(validate_patch(&patch));},"set"=>{let Some(s)=input else{eprintln!("set requires patch JSON");process::exit(64)};let mut patch:Value=serde_json::from_str(&s).unwrap_or_else(|e|{eprintln!("invalid patch JSON: {e}");process::exit(64)});if let Some(expected)=a.next(){patch["__revision"]=Value::String(expected)}output(set(&path,&patch));},_=>{eprintln!("unknown command");process::exit(64)}}}
